// ─── File: WindowDemo.java ───
// Mirrors SQL window functions: running total, LAG, 3-row moving average.
package com.bank.window;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.*;

public class WindowDemo {
    private static final Logger log = Logger.getLogger(WindowDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnRepository repo = new TxnRepository();
        StatementAnalyticsService service = new StatementAnalyticsService(repo);

        log.info("=== Statement analytics (window functions, rows NOT collapsed) ===");
        for (AnalyticsRow r : service.analyze("SAV2001")) {
            log.info(() -> String.format(
                "%s amount=Rs.%s running=Rs.%s prev=%s mavg3=Rs.%s",
                r.txnId, r.amount, r.runningTotal,
                r.prevAmount == null ? "NULL" : "Rs." + r.prevAmount, r.movingAvg3));
        }
    }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId; final BigDecimal amount; final String createdAt;
    Txn(String id, String acct, BigDecimal amt, String at) {
        this.txnId = id; this.accountId = acct; this.amount = amt; this.createdAt = at;
    }
}

// ─── Would be in model/AnalyticsRow.java ───
class AnalyticsRow {
    final String txnId; final BigDecimal amount, runningTotal, prevAmount, movingAvg3;
    AnalyticsRow(String id, BigDecimal amt, BigDecimal run, BigDecimal prev, BigDecimal mavg) {
        this.txnId = id; this.amount = amt; this.runningTotal = run;
        this.prevAmount = prev; this.movingAvg3 = mavg;
    }
}

// ─── Would be in repository/TxnRepository.java ───
class TxnRepository {
    List<Txn> findByAccountOrdered(String accountId) {
        // already ordered by created_at (the window ORDER BY)
        return List.of(
            new Txn("TX1", accountId, new BigDecimal("10000"), "2026-10-01"),
            new Txn("TX2", accountId, new BigDecimal("20000"), "2026-10-02"),
            new Txn("TX3", accountId, new BigDecimal("5000"),  "2026-10-03"),
            new Txn("TX4", accountId, new BigDecimal("30000"), "2026-10-04"));
    }
}

// ─── Would be in service/StatementAnalyticsService.java ───
class StatementAnalyticsService {
    private final TxnRepository repo;
    StatementAnalyticsService(TxnRepository repo) { this.repo = repo; }

    List<AnalyticsRow> analyze(String accountId) {
        List<Txn> rows = repo.findByAccountOrdered(accountId); // PARTITION BY + ORDER BY
        List<AnalyticsRow> out = new ArrayList<>();
        BigDecimal running = BigDecimal.ZERO;

        for (int i = 0; i < rows.size(); i++) {
            Txn cur = rows.get(i);
            // running total: UNBOUNDED PRECEDING .. CURRENT ROW
            running = running.add(cur.amount);
            // LAG(amount): previous row, NULL on first
            BigDecimal prev = (i == 0) ? null : rows.get(i - 1).amount;
            // moving avg over ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
            int from = Math.max(0, i - 2);
            BigDecimal sum = BigDecimal.ZERO; int cnt = 0;
            for (int j = from; j <= i; j++) { sum = sum.add(rows.get(j).amount); cnt++; }
            BigDecimal mavg = sum.divide(BigDecimal.valueOf(cnt), 2, RoundingMode.HALF_UP);

            out.add(new AnalyticsRow(cur.txnId, cur.amount, running, prev, mavg));
        }
        return out; // one row per input row — NOT collapsed
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
